nextflow_process {
    name "BCFTOOLS_SORT"
    script "../main.nf"
    process "BCFTOOLS_SORT"

    test("sort and index VCF") {
        options "-with-docker"

        when {
            process {
                """
                input[0] = record(id: 'sample', vcf: file("${moduleDir}/tests/data/sample.calls.vcf", checkIfExists: true))
                """
            }
        }

        then {
            assert process.success
            assert file(process.out[0].vcf[0]).size() > 0
            assert file(process.out[0].tbi[0]).size() > 0
        }
    }
}
